(r/'site/viewer-access.html').write_text('<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>View-only access · Tharon Leads</title><link rel="stylesheet" href="/auth.css"></head><body><main class="auth-card"><img src="/brand/tharon-group.png" alt="Tharon Group" width="220"><h1>Opening Tharon Leads</h1><p id="accessMessage" role="status">Opening your view-only access…</p><p><a href="/login">Staff sign-in</a></p></main><script src="/access.js"></script></body></html>\n')
(r/'site/viewer.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>View-only · Tharon Leads</title><link rel="stylesheet" href="/viewer.css"></head><body><header><img src="/brand/tharon-group.png" alt="Tharon Group"><span class="badge">View-only access</span><button id="logout">Sign out</button></header><main><h1>Tharon Leads</h1><p>Browse referrals and buildings. Changes are disabled for this access link.</p><nav><button id="leadsTab">Referrals</button><button id="buildingsTab">Buildings</button><button id="refresh">Refresh</button></nav><section id="filters"><label>Search<input id="search" type="search" placeholder="Resident, building, CCA"></label><label>Waiting on<select id="cca"><option value="all">All CCAs</option></select></label></section><p id="status" role="status">Loading…</p><section id="content"></section><section id="detail" hidden></section></main><script src="/libertana.js"></script><script src="/county-roadmap.js"></script><script src="/referral-progress.js"></script><script src="/viewer.js"></script></body></html>\n')
(r/'site/viewer.js').write_text('(function(){\n\'use strict\';\nconst $=s=>document.querySelector(s),esc=v=>String(v??\'\').replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));\nlet state,csrf,tab=\'leads\';\nconst building=id=>state.buildings.find(b=>b.id===id),staff=id=>state.users.find(u=>u.id===id)?.name||\'Unassigned\',name=l=>[l.first,l.last].filter(Boolean).join(\' \');\nconst summary=l=>window.TLReferral.summary(l,building(l.building),new Date().toLocaleDateString(\'en-CA\',{timeZone:\'America/Los_Angeles\'}));\nasync function load(){try{const r=await fetch(\'/api/state\',{credentials:\'same-origin\'});if(r.status===401){location.replace(\'/viewer-access\');return;}if(!r.ok)throw Error(\'Unable to load referrals. Please refresh.\');const b=await r.json();state=b.state;csrf=b.csrf;const selected=$(\'#cca\').value;const cc=new Map();for(const l of state.leads)if(summary(l).waiting)cc.set(window.TLReferral.ccaKey(l.cca),l.cca?.trim()||\'CCA not recorded\');$(\'#cca\').innerHTML=\'<option value="all">All CCAs</option>\'+[...cc].sort((a,b)=>a[1].localeCompare(b[1])).map(([k,v])=>`<option value="${esc(k)}">${esc(v)}</option>`).join(\'\');if(cc.has(selected))$(\'#cca\').value=selected;render();}catch(e){$(\'#status\').textContent=e.message;}}\nfunction render(){if(!state)return;$(\'#detail\').hidden=true;const q=$(\'#search\').value.trim().toLowerCase(),cca=$(\'#cca\').value;$(\'#filters\').hidden=tab===\'buildings\';if(tab===\'buildings\'){$(\'#status\').textContent=state.buildings.length+\' buildings\';$(\'#content\').innerHTML=state.buildings.map(b=>`<article class="card"><h2>${esc(b.name||b.short)}</h2><p>${esc(b.county||\'\')}</p><p>${state.leads.filter(l=>l.building===b.id&&![\'lost\',\'movein\'].includes(l.stage)).length} open referrals</p></article>`).join(\'\');return;}\nconst ls=state.leads.filter(l=>(!q||[name(l),building(l.building)?.name,l.cca].join(\' \').toLowerCase().includes(q))&&(cca===\'all\'||window.TLReferral.matchesWaitingCCA(l,summary(l),cca)));\n$(\'#status\').textContent=ls.length+\' referrals\';$(\'#content\').innerHTML=ls.map(l=>{const p=summary(l);return `<article class="card"><p class="muted">${esc(building(l.building)?.name||\'Unassigned building\')}</p><h2>${esc(name(l))}</h2><p>${esc(p.label)}</p><p class="muted">CCA: ${esc(l.cca||\'Not recorded\')}</p>${p.waitingSince?`<p class="muted">Waiting for approval since ${esc(p.waitingSince)} · ${p.waitingDays} days</p>`:\'\'}<button data-lead="${esc(l.id)}">View profile</button></article>`;}).join(\'\')||\'<p>No referrals match.</p>\';}\nfunction detail(id){const l=state.leads.find(x=>x.id===id);if(!l)return;const p=summary(l),row=(k,v)=>`<dt>${esc(k)}</dt><dd>${esc(v||\'Not recorded\')}</dd>`;$(\'#detail\').innerHTML=`<button id="closeDetail">Close profile</button><h2>${esc(name(l))}</h2><span class="badge">Read only</span><dl>${row(\'Building\',building(l.building)?.name)}${row(\'Lead owner\',staff(l.rep))}${row(\'Age\',l.age)}${row(\'Program\',l.payer)}${row(\'CCA\',l.cca)}${row(\'Progress\',p.label)}${row(\'Assessment\',p.assessment===\'accepted\'?\'Yes\':\'Not yet\')}${row(\'Approval\',window.TLReferral.options[p.privatePay?\'payment\':\'approval\'].find(x=>x[0]===p.approval)?.[1])}${row(\'Next step\',p.next)}${row(\'Follow-up\',p.due)}${row(\'Contact\',l.caller?.name)}${row(\'Phone\',l.caller?.phone)}${row(\'Email\',l.caller?.email)}${row(\'Notes\',l.notes)}${row(\'Latest update\',p.note)}</dl><h3>Documents</h3>${(l.files||[]).map(f=>`<p><a href="/api/files/${encodeURIComponent(f.id)}" target="_blank" rel="noopener">${esc(f.name||\'Document\')}</a></p>`).join(\'\')||\'<p>No documents attached.</p>\'}`;$(\'#detail\').hidden=false;$(\'#detail\').scrollIntoView({behavior:\'smooth\'});}\n$(\'#leadsTab\').addEventListener(\'click\',()=>{tab=\'leads\';render();});$(\'#buildingsTab\').addEventListener(\'click\',()=>{tab=\'buildings\';render();});$(\'#search\').addEventListener(\'input\',render);$(\'#cca\').addEventListener(\'change\',render);$(\'#refresh\').addEventListener(\'click\',load);$(\'#content\').addEventListener(\'click\',e=>{const b=e.target.closest(\'[data-lead]\');if(b)detail(b.dataset.lead);});$(\'#detail\').addEventListener(\'click\',e=>{if(e.target.id===\'closeDetail\')$(\'#detail\').hidden=true;});$(\'#logout\').addEventListener(\'click\',async()=>{const r=await fetch(\'/api/logout\',{method:\'POST\',credentials:\'same-origin\',headers:{\'X-CSRF-Token\':csrf}});if(r.ok)location.replace(\'/viewer-access\');else $(\'#status\').textContent=\'Sign-out failed. Please try again.\';});load();\n})();\n')
(r/'site/viewer.css').write_text(':root{font-family:system-ui,sans-serif;color:#193e35;background:#f3f6f3}*{box-sizing:border-box}body{margin:0}header{background:white;display:flex;align-items:center;gap:16px;padding:20px 5%;border-bottom:1px solid #dbe5de}header img{width:170px;max-width:38%}.badge{font-size:13px;padding:6px 10px;background:#e8f2ec;border-radius:20px}header button{margin-left:auto}main{max-width:1100px;margin:30px auto;padding:0 20px}h1{margin-bottom:6px}p{line-height:1.5}button,input,select{font:inherit;padding:11px 14px;border:1px solid #c5d4cb;border-radius:8px;background:white;color:inherit}button{cursor:pointer}button:hover{background:#eaf2ed}nav,#filters{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0}label{display:grid;gap:7px}input{min-width:230px}#content{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px}.card,#detail{background:white;border:1px solid #dbe5de;border-radius:14px;padding:22px}.card h2{font-size:19px;margin-top:0}.muted{color:#62756d;font-size:14px}dl{display:grid;grid-template-columns:minmax(100px,1fr) 2fr;gap:12px}dt{color:#62756d}dd{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}#detail{margin-top:20px}a{color:#145c48}.note{white-space:pre-wrap}#status{color:#62756d}#detail[hidden]{display:none}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #6ca88b;outline-offset:2px}\n')
(r/'test/view-only-access.test.mjs').write_text("import test from 'node:test';import assert from 'node:assert/strict';import {mkdtempSync,rmSync} from 'node:fs';import {tmpdir} from 'node:os';import path from 'node:path';import {randomBytes,createHmac,randomUUID} from 'node:crypto';\nimport {createApplication} from '../server/index.mjs';import {hash} from '../server/security.mjs';import {execute,initialState} from '../server/engine.mjs';\ntest('viewer link reads every building and lead, denies all writes, stays separate from admin access and can be revoked',async()=>{\n const dir=mkdtempSync(path.join(tmpdir(),'tharon-viewer-')),access=randomBytes(32).toString('hex'),adminAccess=randomBytes(32).toString('hex'),secret='viewer-test-secret';\n const env={NODE_ENV:'test',APP_MODE:'live',PHI_APPROVED:'true',SQLITE_PATH:path.join(dir,'state.sqlite'),SESSION_SECRET:secret,VIEWER_ACCESS_HASH:hash(access),VIEWER_ACCESS_EXPIRES_AT:new Date(Date.now()+3600000).toISOString(),DELEGATE_ACCESS_HASH:hash(adminAccess),DELEGATE_ACCESS_EXPIRES_AT:new Date(Date.now()+3600000).toISOString()};\n const app=await createApplication({env,schedule:false});await new Promise(r=>app.server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+app.server.address().port;\n const fake=execute(initialState(false),'u0',{op:'createLead',createdId:'L_viewer_example',args:[{first:'Fictional',last:'Viewer',building:'hallmark',rep:'u3',payer:'Private pay'}]});\n await app.store.query('UPDATE app_state SET data=$1 WHERE id=$2',[JSON.stringify(fake),'main']);\n const login=t=>fetch(origin+'/auth/viewer-access',{method:'POST',headers:{Origin:origin,'Content-Type':'application/json'},body:JSON.stringify({token:t})});\n try{\n assert.equal((await login('bad')).status,403);assert.equal((await login(adminAccess)).status,403);\n const r=await login(access);assert.equal(r.status,200);const cookie=r.headers.get('set-cookie').split(';')[0],headers={Cookie:cookie,Origin:origin};\n const boot=await (await fetch(origin+'/api/state',{headers})).json();assert.equal(boot.state.me,'u5');assert.equal(boot.state.users.find(u=>u.id==='u5').role,'viewer');assert.ok(boot.state.buildings.length>3);assert.equal(boot.state.leads[0].id,'L_viewer_example');assert.ok(!JSON.stringify(boot).includes(access));\n assert.equal((await fetch(origin+'/viewer',{headers})).status,200);assert.equal((await fetch(origin+'/',{headers,redirect:'manual'})).headers.get('location'),'/viewer');\n const initial=(await app.store.query('SELECT data FROM app_state WHERE id=$1',['main']))[0].data;\n for(const endpoint of ['/api/commands','/api/import','/api/files','/api/extract-lead','/api/transcribe','/api/users/password','/api/push/subscribe']){\n const res=await fetch(origin+endpoint,{method:'POST',headers:{...headers,'X-CSRF-Token':boot.csrf,'Content-Type':'application/json'},body:JSON.stringify({id:randomUUID(),op:'createLead',args:[]})});assert.equal(res.status,403,endpoint);\n }\n assert.equal((await app.store.query('SELECT data FROM app_state WHERE id=$1',['main']))[0].data,initial);\n assert.equal((await fetch(origin+'/api/users',{headers})).status,403);\n assert.throws(()=>execute(initialState(false),'u5',{op:'createLead',args:[{}]}),/View-only/);\n const t='admin-viewer-revocation';await app.store.query('INSERT INTO sessions (token_hash,user_id,expires_at,csrf) VALUES ($1,$2,$3,$4)',[createHmac('sha256',secret).update(t).digest('hex'),'u0',Date.now()+60000,'admin-csrf']);\n assert.equal((await fetch(origin+'/api/admin/viewer-access',{method:'DELETE',headers:{Cookie:'tl_session='+t,Origin:origin,'X-CSRF-Token':'admin-csrf'}})).status,200);\n assert.equal((await fetch(origin+'/api/state',{headers})).status,401);assert.equal((await login(access)).status,403);\n assert.ok(!(await app.store.query('SELECT * FROM audit_log')).some(x=>JSON.stringify(x).includes(access)));\n }finally{await app.close();rmSync(dir,{recursive:true,force:true});}\n});\n")
