(r/'test/viewer-no-expiry.test.mjs').write_text("import test from 'node:test';import assert from 'node:assert/strict';import {mkdtempSync,rmSync} from 'node:fs';import {tmpdir} from 'node:os';import path from 'node:path';import {randomBytes,createHmac} from 'node:crypto';import {createApplication} from '../server/index.mjs';import {hash} from '../server/security.mjs';\nasync function fixture(expiry){const dir=mkdtempSync(path.join(tmpdir(),'viewer-expiry-')),token=randomBytes(32).toString('hex'),secret='viewer-expiry-test-secret';const app=await createApplication({env:{NODE_ENV:'test',APP_MODE:'live',PHI_APPROVED:'true',SQLITE_PATH:path.join(dir,'db.sqlite'),SESSION_SECRET:secret,VIEWER_ACCESS_HASH:hash(token),VIEWER_ACCESS_EXPIRES_AT:expiry},schedule:false});await new Promise(r=>app.server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+app.server.address().port;return {app,token,secret,origin,login:()=>fetch(origin+'/auth/viewer-access',{method:'POST',headers:{Origin:origin,'Content-Type':'application/json'},body:JSON.stringify({token})}),close:async()=>{await app.close();rmSync(dir,{recursive:true,force:true});}};}\ntest('explicit non-expiring viewer link survives future dates, remains view-only and can be revoked',async()=>{const f=await fixture('never'),realNow=Date.now;try{Date.now=()=>realNow()+366*86400000;const login=await f.login();assert.equal(login.status,200);Date.now=realNow;const cookie=login.headers.get('set-cookie').split(';')[0];const boot=await (await fetch(f.origin+'/api/state',{headers:{Cookie:cookie}})).json();assert.equal(boot.state.users.find(u=>u.id===boot.state.me).role,'viewer');const row=(await f.app.store.query('SELECT expires_at FROM sessions WHERE user_id=$1',['u5']))[0];assert.ok(Number.isFinite(Number(row.expires_at)));const admin='admin-expiry-test';await f.app.store.query('INSERT INTO sessions (token_hash,user_id,expires_at,csrf) VALUES ($1,$2,$3,$4)',[createHmac('sha256',f.secret).update(admin).digest('hex'),'u0',Date.now()+60000,'csrf']);const headers={Cookie:'tl_session='+admin,Origin:f.origin,'X-CSRF-Token':'csrf'};const settings=await (await fetch(f.origin+'/api/admin/viewer-access',{headers})).json();assert.equal(settings.active,true);assert.equal(settings.expiresAt,null);assert.equal((await fetch(f.origin+'/api/admin/viewer-access',{method:'DELETE',headers})).status,200);assert.equal((await f.login()).status,403);}finally{Date.now=realNow;await f.close();}});\ntest('missing, malformed and expired viewer dates do not grant indefinite access',async()=>{for(const expiry of ['', 'invalid', '2020-01-01T00:00:00Z']){const f=await fixture(expiry);try{assert.equal((await f.login()).status,403,expiry);}finally{await f.close();}}});\n")
